        self.detectors = {
            'execution': ExecutionErrorDetector(),
            'semantic': SemanticErrorDetector(),
            'contextual': ContextualErrorDetector(),
            'pattern': PatternErrorDetector()
        }

    def analyze(self, execution_result, context):
        errors = {}
        for name, detector in self.detectors.items():
