class ErrorCatalog:
    """Index des erreurs et contextes"""

    def __init__(self):
        self.catalog = {}

    def add(self, error_type, error_info):
        if error_type not in self.catalog:
            self.catalog[error_type] = []
        self.catalog[error_type].append({
            'info': error_info,
            'frequency': 1,
            'last_seen': time.time()
        })

    def find_similar(self, domain=None):
        """Retrouver erreurs similaires"""
        results = []
        for error_type, instances in self.catalog.items():
            for instance in instances:
                if domain is None or instance['info'].get('domain') == domain:
                    results.append((error_type, instance))
        return sorted(results, key=lambda x: x[1]['frequency'], reverse=True)

