class BehavioralAdapter:
    """Adaptation progressive du comportement"""

    def __init__(self):
        self.behavior_weights = {}
        self.adaptation_rate = 0.1
        self.consolidation_threshold = 5  # Nombre d'occurrences avant consolidation

    def update(self, reflection):
        error_type = reflection['error_type']
        solution = reflection['solution']

        # Mise à jour court-terme
        self._update_weights(error_type, solution, immediate=True)

        # Consolidation si seuil atteint
        if self._should_consolidate(error_type):
            self._consolidate_learning(error_type)

    def _update_weights(self, error_type, solution, immediate=False):
        key = (error_type, solution)
        if key not in self.behavior_weights:
            self.behavior_weights[key] = {
                'weight': 0.5,
                'count': 0,
                'success_rate': 0.0
            }

        entry = self.behavior_weights[key]
        entry['count'] += 1

        # Renforcement progressif
        if immediate:
            entry['weight'] += self.adaptation_rate * (1 - entry['weight'])

        entry['success_rate'] = entry['weight']

    def _should_consolidate(self, error_type):
        count = sum(1 for (et, _), v in self.behavior_weights.items() 
                   if et == error_type)
        return count >= self.consolidation_threshold

    def _consolidate_learning(self, error_type):
        """Passer du court-terme au long-terme"""
        relevant = [(k, v) for k, v in self.behavior_weights.items() 
                   if k[0] == error_type]

        best_solution = max(relevant, key=lambda x: x[1]['success_rate'])

        return {
            'consolidated_rule': {
                'error_type': error_type,
                'preferred_solution': best_solution[0][1],
                'confidence': best_solution[1]['success_rate']
            }
        }

    def get_next_behavior(self, error_type):
        """Sélectionner comportement adapté"""
        candidates = [(k, v) for k, v in self.behavior_weights.items() 
                     if k[0] == error_type]

        if not candidates:
            return 'default_strategy'

        return max(candidates, key=lambda x: x[1]['weight'])[0][1]
