class InformationPriority:
    """Système de scoring multi-critères pour la mémorisation"""

    def __init__(self):
        self.weights = {
            'frequency': 0.30,      # Fréquence d'accès
            'decision_impact': 0.25, # Impact décisionnel
            'recalc_cost': 0.20,    # Coût de recalcul
            'immediacy': 0.15,      # Pertinence immédiate
            'entropy_reduction': 0.10 # Réduction d'incertitude
        }

    def calculate_score(self, info_metadata):
        """
        Calcule le score de priorité d'une information

        Args:
            info_metadata: {
                'access_count': int,
                'last_access': timestamp,
                'decision_impact': float [0-1],
                'recalc_cost': float [0-1],
                'context_relevance': float [0-1],
                'entropy_reduction': float [0-1],
                'age': int (cycles)
            }
        """
        score = 0

        # 1. Fréquence normalisée (accès par cycle)
        freq_score = min(info_metadata['access_count'] / 10, 1.0)

        # 2. Impact décisionnel (direct)
        decision_score = info_metadata['decision_impact']

        # 3. Coût de recalcul (plus élevé = plus prioritaire)
        recalc_score = info_metadata['recalc_cost']

        # 4. Pertinence immédiate (décroît avec l'âge)
        decay_factor = 0.95 ** info_metadata['age']
        immediacy_score = info_metadata['context_relevance'] * decay_factor

        # 5. Entropie informationnelle
        entropy_score = info_metadata['entropy_reduction']

        # Score pondéré
        score = (
            self.weights['frequency'] * freq_score +
            self.weights['decision_impact'] * decision_score +
            self.weights['recalc_cost'] * recalc_score +
            self.weights['immediacy'] * immediacy_score +
            self.weights['entropy_reduction'] * entropy_score
        )

        return score
