class EvictionStrategies:
    """Comparaison de 7 stratégies d'éviction"""

    @staticmethod
    def fifo(memory, capacity):
        """First In First Out - baseline"""
        if len(memory) >= capacity:
            oldest = min(memory.items(), key=lambda x: x[1]['timestamp'])
            del memory[oldest[0]]

    @staticmethod
    def lru(memory, capacity):
        """Least Recently Used - standard"""
        if len(memory) >= capacity:
            lru_item = min(memory.items(), key=lambda x: x[1]['last_access'])
            del memory[lru_item[0]]

    @staticmethod
    def priority_based(memory, capacity, priority_scores):
        """Basé sur le score de priorité calculé"""
        if len(memory) >= capacity:
            lowest_priority = min(
                memory.items(),
                key=lambda x: priority_scores.get(x[0], 0)
            )
            del memory[lowest_priority[0]]

    @staticmethod
    def entropy_based(memory, capacity):
        """Conserve les infos réduisant l'entropie"""
        if len(memory) >= capacity:
            lowest_entropy = min(
                memory.items(),
                key=lambda x: x[1]['entropy_reduction']
            )
            del memory[lowest_entropy[0]]

    @staticmethod
    def graceful_degradation(memory, capacity, compression_ratio=0.7):
        """Dégradation progressive au lieu d'éviction brutale"""
        if len(memory) >= capacity:
            # Compresser les 30% les moins prioritaires
            to_compress = int(len(memory) * (1 - compression_ratio))
            candidates = sorted(
                memory.items(),
                key=lambda x: x[1]['priority_score']
            )[:to_compress]

            for key, info in candidates:
                # Réduire la granularité/détail
                info['compressed'] = True
                info['detail_level'] = 0.5

    @staticmethod
    def domain_selective(memory, capacity, current_task_domain):
        """Mémorisation sélective par domaine"""
        if len(memory) >= capacity:
            # Éviter les infos hors du domaine courant
            out_of_domain = [
                (k, v) for k, v in memory.items()
                if v.get('domain') != current_task_domain
            ]

            if out_of_domain:
                to_remove = min(out_of_domain, 
                               key=lambda x: x[1]['priority_score'])
                del memory[to_remove[0]]
            else:
                # Fallback: éviction par priorité
                lowest = min(memory.items(),
                           key=lambda x: x[1]['priority_score'])
                del memory[lowest[0]]

    @staticmethod
    def hybrid_adaptive(memory, capacity, priority_scores, context):
        """Stratégie hybride: fréquence + impact + coût"""
        if len(memory) >= capacity:
            scores = {}
            for key, info in memory.items():
                hybrid_score = (
                    0.35 * (info['access_count'] / 10) +  # Fréquence
                    0.40 * info['decision_impact'] +        # Impact
                    0.25 * info['recalc_cost']              # Coût
                )
                scores[key] = hybrid_score

            lowest = min(scores.items(), key=lambda x: x[1])
            del memory[lowest[0]]
