class AdaptiveMemorySystem:
    """Apprentissage des priorités par retour d'expérience"""

    def __init__(self, capacity=100):
        self.memory = {}
        self.capacity = capacity
        self.priority_calculator = InformationPriority()
        self.eviction_strategy = 'hybrid_adaptive'
        self.performance_log = []
        self.weight_history = []

    def store(self, key, content, metadata):
        """Stocke une information avec métadonnées"""
        self.memory[key] = {
            'content': content,
            'timestamp': time.time(),
            'last_access': time.time(),
            'access_count': 0,
            'age': 0,
            **metadata
        }

        # Appliquer la stratégie d'éviction si nécessaire
        if len(self.memory) > self.capacity:
            self._evict()

    def retrieve(self, key):
        """Récupère et met à jour les métadonnées"""
        if key in self.memory:
            self.memory[key]['last_access'] = time.time()
            self.memory[key]['access_count'] += 1
            return self.memory[key]['content']
        return None

    def _evict(self):
        """Applique la stratégie d'éviction courante"""
        priority_scores = {
            k: self.priority_calculator.calculate_score(v)
            for k, v in self.memory.items()
        }

        if self.eviction_strategy == 'hybrid_adaptive':
            EvictionStrategies.hybrid_adaptive(
                self.memory, self.capacity, priority_scores, {}
            )

    def measure_performance(self, task_results):
        """Mesure l'impact de la stratégie sur la performance"""
        metrics = {
            'hit_rate': task_results.get('cache_hits', 0) / 
                       max(task_results.get('total_accesses', 1), 1),
            'avg_retrieval_time': task_results.get('avg_time', 0),
            'memory_utilization': len(self.memory) / self.capacity,
            'recalc_cost_avoided': task_results.get('recalc_saved', 0),
            'decision_quality': task_results.get('quality_score', 0)
        }

        self.performance_log.append(metrics)
        return metrics

    def adapt_weights(self, performance_delta):
        """Ajuste les poids selon les performances"""
        if performance_delta > 0:
            # Renforcer les critères qui ont bien fonctionné
            for criterion in ['frequency', 'decision_impact']:
                self.priority_calculator.weights[criterion] *= 1.05
        else:
            # Réduire les critères inefficaces
            for criterion in ['immediacy']:
                self.priority_calculator.weights[criterion] *= 0.95

        # Normaliser
        total = sum(self.priority_calculator.weights.values())
        for k in self.priority_calculator.weights:
            self.priority_calculator.weights[k] /= total

        self.weight_history.append(
            self.priority_calculator.weights.copy()
        )
