class ImpactScorer:
    def score(self, info: dict) -> float:
        """
        Score = (impact × fréquence_accès × validité) / (temps_depuis_accès + 1)
        """
        impact = info.get('impact', 0)
        frequency = info.get('access_frequency', 1)
        validity = info.get('validity_duration', 1)
        recency = info.get('cycles_since_access', 1)

        score = (impact * frequency * validity) / (recency + 1)
        return round(score, 3)

    def classify(self, score: float) -> str:
