class MemoryStrategy:

    # STRATÉGIE 1: Seuil simple
    @staticmethod
    def strategy_1_threshold(items: list) -> dict:
        keep = [i for i in items if i['impact'] >= 0.60]
        evict = [i for i in items if i['impact'] < 0.50]
        return {'keep': keep, 'evict': evict, 'name': 'Threshold'}

    # STRATÉGIE 2: Pondération dynamique
    @staticmethod
    def strategy_2_weighted(items: list) -> dict:
        scored = [(i, i['impact'] * i.get('frequency', 1)) for i in items]
        threshold = sum(s[1] for s in scored) / len(scored) * 0.75
        keep = [s[0] for s in scored if s[1] >= threshold]
        evict = [s[0] for s in scored if s[1] < threshold * 0.5]
        return {'keep': keep, 'evict': evict, 'threshold': threshold, 'name': 'Weighted'}

    # STRATÉGIE 3: Hiérarchisée
    @staticmethod
    def strategy_3_hierarchical(items: list) -> dict:
        L1 = [i for i in items if i['impact'] >= 0.70]  # Critique
        L2 = [i for i in items if 0.50 <= i['impact'] < 0.70]  # Utile
        L3 = [i for i in items if i['impact'] < 0.50]  # Externe
        return {'L1': L1, 'L2': L2, 'L3': L3, 'name': 'Hierarchical'}

    # STRATÉGIE 4: Éviction basée sur coût
    @staticmethod
    def strategy_4_eviction_cost(items: list) -> dict:
        scored = [(i, (1 - i['impact']) * (i.get('cycles_since_access', 1) + 1)) 
                  for i in items]
        scored.sort(key=lambda x: x[1], reverse=True)
        threshold = len(items) * 0.7
        keep = [s[0] for s in scored[:int(threshold)]]
        evict = [s[0] for s in scored[int(threshold):]]
        return {'keep': keep, 'evict': evict, 'name': 'EvictionCost'}

    # STRATÉGIE 5: Apprentissage par renforcement
    @staticmethod
    def strategy_5_reinforcement(items: list, history: list) -> dict:
        # Analyse des 4 cycles réussis
        success_patterns = [h for h in history if h['success']]
        if success_patterns:
            avg_impact = sum(h['avg_impact'] for h in success_patterns) / len(success_patterns)
            keep = [i for i in items if i['impact'] >= avg_impact * 0.9]
            evict = [i for i in items if i['impact'] < avg_impact * 0.5]
        else:
            keep, evict = items[:int(len(items)*0.7)], items[int(len(items)*0.7):]
        return {'keep': keep, 'evict': evict, 'name': 'Reinforcement'}

    # STRATÉGIE 6: Distribuée multi-agent
